/**
 * The mockup kit (docs/feat/mobile-mockup-kit.md Slice 2): an ES module with no
 * dependencies and no build step.
 *
 * - PURE builders (no DOM): `K.<component>(props) → { html, a11y }`, runnable
 *   under Bun (tests, calibration). States are the code's own names.
 * - `K.screen(el, opts, children)` mounts a phone into a DOM element.
 *
 * Every number/colour is a CSS var from generated/tokens.css; every decision a
 * pure app module makes is read from `KIT.data.viewModels` (generated by
 * evaluating that module), never re-derived here. Anything not in the kit is
 * built with `K.extend(name, builder)` and shows as «nuovo».
 */
import data from "./generated/kit-data.json" with { type: "json" };

export const KIT = { data };

const ESC = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" };
/** HTML-escape a text. */
export const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ESC[c]);
const out = (html, a11y = "") => ({ html, a11y });
const join = (parts) => parts.map((p) => (typeof p === "string" ? p : p.html)).join("");

// ── markdown subset (p, strong/em, inline code, code block, list, link) ──────
function inline(text) {
  return esc(text)
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/\*([^*]+)\*/g, "<em>$1</em>")
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
}

/** A small markdown → the transcript's block styles (`Markdown.tsx` metrics). */
export function markdown(src) {
  const blocks = [];
  const lines = String(src).split("\n");
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i] ?? "";
    if (line.startsWith("```")) {
      const lang = line.slice(3).trim();
      const body = [];
      for (i += 1; i < lines.length && !(lines[i] ?? "").startsWith("```"); i += 1)
        body.push(lines[i]);
      blocks.push(
        `<pre><div class="k-code-head">${esc(lang || "code")}</div><code>${esc(body.join("\n"))}</code></pre>`,
      );
    } else if (/^[-*] /.test(line)) {
      const items = [];
      for (; i < lines.length && /^[-*] /.test(lines[i] ?? ""); i += 1)
        items.push(`<li><span>${inline((lines[i] ?? "").slice(2))}</span></li>`);
      i -= 1;
      blocks.push(`<ul>${items.join("")}</ul>`);
    } else if (line.trim() !== "") {
      blocks.push(`<p>${inline(line)}</p>`);
    }
  }
  return blocks.join("");
}

// ── iPhone components ─────────────────────────────────────────────────────
const vm = data.viewModels;
const glyphs = data.glyphs;

/** The status bar: 9:41, the island, the battery. */
function statusBar() {
  return '<div class="k-phone-status"><span>9:41</span><span class="k-phone-batt"></span></div><div class="k-phone-island"></div>';
}

/** The device frame around `children`; `bare` drops the bezel (calibration). */
export function phone(
  { theme = "light", font = "system", bare = false, reduceMotion = false } = {},
  children = [],
) {
  const attrs = [
    `data-theme="${esc(theme)}"`,
    font === "figtree" ? 'data-font="figtree"' : "",
    bare ? "data-bare" : "",
    reduceMotion ? "data-reduce-motion" : "",
  ].join(" ");
  return out(
    `<div class="k-phone" ${attrs}>${statusBar()}<div class="k-phone-screen">${join(children)}</div><div class="k-phone-indicator"></div></div>`,
  );
}

/** The header dot: `HeaderDot`'s states, look from `chat-header.ts` `dotLook`. */
export function headerDot(dot) {
  if (dot === "idle" || dot === undefined) return out("");
  const look = vm.headerDot[dot];
  if (!look) throw new Error(`K.headerDot: unknown dot "${dot}"`);
  return out(toneDot(look.tone, look), dot);
}

/** `StatusDot.toneColor`, mapped by hand (a component, not a pure module). */
const TONE = {
  online: "var(--c-green)",
  running: "var(--c-accent)",
  attention: "var(--c-orange)",
  offline: "var(--c-sec)",
  wait: "var(--c-sec)",
};

/** A status dot of `tone`: filled, or a ring (`hollow`), optionally pulsing. */
function toneDot(tone, { hollow = false, pulse = false } = {}) {
  const a = [hollow ? "data-hollow" : "", pulse ? "data-pulse" : ""].join(" ");
  return `<span class="k-dot" ${a} style="color:${TONE[tone]}"></span>`;
}

/** The chat header: back, title (+ dot), model subtitle, the `…` menu. */
export function sessionHeader({ title = "Session", subtitle = "", dot = "idle" } = {}) {
  return out(
    `<div class="k-header"><div class="k-header-side"><span class="k-icon-btn">‹</span></div><div class="k-header-title"><div class="k-header-line k-t-headline">${headerDot(dot).html}<span>${esc(title)}</span></div>${subtitle ? `<span class="k-t-caption k-sec">${esc(subtitle)}</span>` : ""}</div><div class="k-header-side" data-right><span class="k-icon-btn">…</span></div></div>`,
    title,
  );
}

export function userBubble({ text }) {
  return out(
    `<div class="k-row"><div class="k-bubble k-t-bubble">${inline(text)}</div></div>`,
    text,
  );
}

export function assistantText({ markdown: md }) {
  return out(`<div class="k-row"><div class="k-md">${markdown(md)}</div></div>`, md);
}

function therefore({ breathe = false, color = "var(--c-sec)" } = {}) {
  const at = data.metrics.step.consts.DOT_AT;
  const dots = vm.breathe.dotOrder
    .map((pos, i) => {
      const p = at[pos];
      const anim = breathe ? `animation-name:k-breathe-${i};` : "";
      return `<i style="left:${p.left}px;top:${p.top}px;${anim}"></i>`;
    })
    .join("");
  return `<span class="k-therefore" ${breathe ? "data-breathe" : ""} style="color:${color}">${dots}</span>`;
}

const NODE = {
  ok: () => '<span class="k-node-dot" data-kind="ok"></span>',
  error: () => '<span class="k-node-dot" data-kind="error"></span>',
  running: () => '<span class="k-node-dot" data-kind="running"></span>',
  pending: () => '<span class="k-node-ring"></span>',
  thought: () => therefore(),
  thinking: () => therefore({ breathe: true, color: "var(--c-accent)" }),
  wake: () => `<span class="k-node-wake">${esc(glyphs.wake)}</span>`,
};

/**
 * One step on the rail (`StepNode`): `node` ∈ ok | error | running | pending |
 * thought | thinking | wake; `up`/`down` = `ThreadPos`; `body` = a `stepBody`.
 */
export function stepNode({
  node = "ok",
  name = "",
  subtitle = "",
  up = false,
  down = false,
  body = null,
  error = false,
} = {}) {
  const draw = NODE[node];
  if (!draw) throw new Error(`K.stepNode: unknown node "${node}"`);
  let line;
  if (node === "thinking") {
    const label = vm.thinkingLabel["3000"];
    line = `<span class="k-t-step k-shimmer">${esc(label.word)}</span><span class="k-t-step-mono k-sec k-tabular">${esc(label.seconds)}</span>`;
  } else if (node === "thought") {
    line = `<span class="k-t-step k-sec" style="font-style:italic">Thought</span><span class="k-step-sub k-t-step-mono">${esc(subtitle || vm.thoughtRow["12000"].subtitle)}</span>`;
  } else {
    line = `<span class="k-step-name k-t-step">${esc(name)}</span><span class="k-step-sub k-t-step-mono" ${error || node === "error" ? "data-error" : ""}>${esc(subtitle)}</span>`;
  }
  return out(
    `<div class="k-step"><div class="k-step-gutter">${up ? '<i class="k-thread" data-up></i>' : ""}${down ? '<i class="k-thread" data-down></i>' : ""}<div class="k-node-box">${draw()}</div></div><div class="k-step-col"><div class="k-step-line">${line}</div>${body ? body.html : ""}</div></div>`,
    `${name} ${node}`,
  );
}

/** A run of steps, threaded top to bottom. */
export function stepRail(steps) {
  const n = steps.length;
  return out(
    `<div class="k-steps">${steps.map((s, i) => stepNode({ up: i > 0, down: i < n - 1, ...s }).html).join("")}</div>`,
  );
}

/** A step's open body: mono lines; `+`/`-` lines as a diff; `error` in red. */
export function stepBody({ lines = [], error = false, thought = "" } = {}) {
  const code = lines
    .map((l) => {
      const cls = l.startsWith("+") ? "k-diff-add" : l.startsWith("-") ? "k-diff-del" : "";
      return cls ? `<span class="${cls}">${esc(l)}</span>` : esc(l);
    })
    .join("\n");
  const t = thought
    ? `<div class="k-thought">${therefore()}<span class="k-thought-text">${esc(thought)}</span></div>`
    : "";
  return out(
    `<div class="k-step-body">${t}<pre class="k-step-code" ${error ? "data-error" : ""}>${code}</pre></div>`,
  );
}

/** An orphan thought's row (`thoughtRowView`): folded, never expandable. */
export function thoughtRow({ ms = 12000 } = {}) {
  const v = vm.thoughtRow[String(ms)];
  if (!v)
    throw new Error(
      `K.thoughtRow: no view-model for ms=${ms} (have ${Object.keys(vm.thoughtRow)})`,
    );
  return stepNode({ node: "thought", subtitle: v.subtitle });
}

/**
 * The SF Symbols the composer draws (`Icon.tsx` names, weights and sizes from
 * `Composer.tsx`), as thin strokes in `currentColor`: the browser has no SF
 * Symbols, so these are drawn to their proportions (light = a hairline stroke,
 * bold = a heavy one). `size` is the symbol's point size.
 */
const ICON = {
  plus: (w) => `<path d="M10 2.6v14.8M2.6 10h14.8" stroke-width="${w}"/>`,
  mic: (w) =>
    `<rect x="7" y="1.6" width="6" height="10.4" rx="3" stroke-width="${w}"/><path d="M4 9.2a6 6 0 0 0 12 0M10 15.2v3.4M6.8 18.6h6.4" stroke-width="${w}"/>`,
  "arrow.up": (w) => `<path d="M10 17V3.4M4.2 9.2 10 3.4l5.8 5.8" stroke-width="${w}"/>`,
  clock: (w) =>
    `<circle cx="10" cy="10" r="7.8" stroke-width="${w}"/><path d="M10 5.4V10l3 2" stroke-width="${w}"/>`,
  // The ask's origin and action symbols (`ui/AskCard.tsx`, `ui/AskSlim.tsx`).
  "arrow.triangle.branch": (w) =>
    `<path d="M5 3v11.2M5 14.2h1.6M5 14.2H3.4M5 9.6c0-2.3 1.8-3.6 4-3.6h3.4M12 3.2 14.6 6h-2.6z" stroke-width="${w}"/>`,
  "point.topleft.down.to.point.bottomright.curvepath": (w) =>
    `<rect x="1.8" y="3.4" width="3.2" height="3.2" rx="0.7" stroke-width="${w}"/><rect x="15" y="13.4" width="3.2" height="3.2" rx="0.7" stroke-width="${w}"/><path d="M3.4 6.6v3.6c0 2.4 2.4 3.4 5.2 3.4 2.6 0 4.6-.8 5.7-2.4" stroke-width="${w}"/>`,
  "hand.raised": (w) =>
    `<path d="M6.4 16.6c-1.9 0-3.1-1.3-3.1-3.1V9.2c0-.6.4-1 .9-1s.9.4.9 1v1.3M8.2 10.5V4.3c0-.6.4-1 .9-1s.9.4.9 1v6.2M10 10.9V3.3c0-.6.4-1 .9-1s.9.4.9 1v7.6M11.8 10.9V5.3c0-.6.4-1 .9-1s.9.4.9 1v7.5c0 1.9-1.5 3.3-3.4 3.3H9.2" stroke-width="${w}"/>`,
  "chevron.up": (w) => `<path d="M4.6 12.4 10 7l5.4 5.4" stroke-width="${w}"/>`,
  // Three filled dots: the dots are the shape, so no stroke weight applies.
  ellipsis: () =>
    `<circle cx="4.4" cy="10" r="1.15" fill="currentColor" stroke="none"/><circle cx="10" cy="10" r="1.15" fill="currentColor" stroke="none"/><circle cx="15.6" cy="10" r="1.15" fill="currentColor" stroke="none"/>`,
  // `bolt.fill`: the Send now pill's symbol (`Composer.tsx`, 13 pt), filled.
  "bolt.fill": () =>
    `<path d="M11.6 1.8 3.9 11.3h4.6l-1 7 7.6-9.5h-4.6z" fill="currentColor" stroke="none"/>`,
};
const WEIGHT = { light: 1.15, regular: 1.5, bold: 2.3 };
/** An SF Symbol (`Icon.tsx`): `name`, point `size`, `weight` ∈ light | regular | bold. */
export function icon(name, { size = 20, weight = "regular" } = {}) {
  const draw = ICON[name];
  if (!draw) throw new Error(`K.icon: no symbol "${name}" (have ${Object.keys(ICON)})`);
  return out(
    `<svg class="k-sym" width="${size}" height="${size}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${draw(WEIGHT[weight])}</svg>`,
  );
}

/** The 36 pt slot (`Composer.tsx` `slot`): its four faces, as the code paints them. */
const SLOT = {
  // `ready` = the soft strong circle, the ↑ in accent, bold 18.
  send: `<span class="k-slot">${icon("arrow.up", { size: 18, weight: "bold" }).html}</span>`,
  // `up-dim` (empty): no circle at all, the ↑ in `sec` at 0.5.
  disabled: `<span class="k-slot" data-dim><span class="k-dim">${icon("arrow.up", { size: 18, weight: "bold" }).html}</span></span>`,
  // `stop`: a `label` circle, a `page` square.
  stop: '<span class="k-slot" data-stop><span class="k-stop-square"></span></span>',
  // `clock` (send later): a `fill` circle, the clock in `label`, 17.
  later: `<span class="k-slot" data-clock>${icon("clock", { size: 17 }).html}</span>`,
};

/** The mic button's face (`Composer.tsx` mic): idle, listening (halo + ■), finalizing (arc). */
const MIC = {
  idle: `<span class="k-hit"><span class="k-circle">${icon("mic", { size: 22, weight: "light" }).html}</span></span>`,
  dictating:
    '<span class="k-hit"><span class="k-circle" data-strong><span class="k-halo"></span><span class="k-rec-square"></span></span></span>',
  transcribing:
    '<span class="k-hit"><span class="k-circle"><span class="k-arc"></span></span></span>',
};

/**
 * The composer: `state` ∈ empty | draft | ready | dictating | transcribing;
 * `queued` = chips above the bar; `home` = keyboard closed (home indicator);
 * `caption` = the dictation clock beside the mic; `slot` overrides the face
 * (send | disabled | stop | later); `sendNow` = the ⇥ pill is offered;
 * `compact` = the RESTING shape (docs/feat/mobile-composer-compact.md) — ONE
 * row, the input on it as first child, `+` absolute, no dead ↑ (OD2) and no
 * hint while the pill holds the right side (D4). Default: today's open field.
 */
export function composer({
  state = "empty",
  text = "",
  placeholder = "Message tentacle",
  queued = [],
  slot,
  caption = "",
  home = true,
  sendNow = false,
  compact = false,
} = {}) {
  const empty = text === "";
  const mic = MIC[state === "dictating" || state === "transcribing" ? state : "idle"];
  const faceKey = slot ?? (state === "ready" || !empty ? "send" : "disabled");
  // OD2: only the DEAD face is left out; ■ Stop, ↑ and the clock are actions.
  const face = !compact || faceKey !== "disabled" ? SLOT[faceKey] : "";
  // D4: the pill is an action and keeps the row's right side; the hint goes.
  const hint = compact && sendNow ? "" : placeholder;
  const chips = queued.length
    ? `<div class="k-queue">${queued.map((q) => `<div class="k-queue-chip k-t-subhead">${esc(q)}</div>`).join("")}</div>`
    : "";
  // ONE body, both shapes, the input FIRST (`Composer.tsx` `styles.body`).
  const body = `<div class="k-composer-row"${compact ? " data-compact" : ""}><div class="k-input" ${empty ? "data-empty" : ""}>${esc(empty ? hint : text)}</div>${plus(compact)}<span class="k-flex"></span>${sendNow ? SEND_NOW : ""}${caption ? `<span class="k-mic-caption">${esc(caption)}</span>` : ""}${mic}${face}</div>`;
  return out(
    `${chips}<div class="k-composer" ${home ? "data-home" : ""}><div class="k-field">${body}</div></div>`,
    empty ? hint : text,
  );
}

/** The ⇥ Send now pill (`Composer.tsx` `styles.sendNow`): bolt 13 pt, «Send now». */
const SEND_NOW = `<span class="k-send-now">${icon("bolt.fill", { size: 13 }).html}<span>Send now</span></span>`;

/** The `+`: in a body laid out by flow, or absolute on the resting row (`data-abs`). */
const plus = (abs) =>
  `<span class="k-hit"${abs ? " data-abs" : ""}><span class="k-circle">${icon("plus", { size: 20, weight: "light" }).html}</span></span>`;

/** The composer's own buttons, for a «nuovo» layout of them (same markup as `composer`). */
export const composerParts = {
  plus: plus(false),
  mic: MIC,
  slot: SLOT,
  sendNow: SEND_NOW,
};

/** A bottom sheet over the scrim (`Sheet`): grabber, `radius.sheet`. */
export function sheet({ children = [], permission = false } = {}) {
  return out(
    `<div class="k-scrim"><div class="k-sheet" ${permission ? "data-permission" : ""}><span class="k-grabber"></span>${join(children)}</div></div>`,
  );
}

/** The permission sheet's default answers: the daemon's `permissionOptions` order. */
const PERMISSION_OPTIONS = [
  { label: "Allow once", primary: true },
  { label: "Always allow" },
  { label: "Deny" },
];

/**
 * The answer pills: `[{label, primary?}]`, validated — a malformed or empty list
 * is a sheet with no answer, so it throws instead of drawing one.
 */
function permOptions(options) {
  if (!Array.isArray(options) || options.length === 0)
    throw new Error("K.permissionSheet: options must be a non-empty array of {label, primary?}");
  return options
    .map((o) => {
      if (typeof o?.label !== "string" || o.label === "")
        throw new Error(
          "K.permissionSheet: options must be a non-empty array of {label, primary?}",
        );
      return `<span class="k-ask-b"${o.primary ? " data-primary" : ""}>${esc(o.label)}</span>`;
    })
    .join("");
}

/**
 * THE ask's origin row (docs/fix/mobile-ask-surfaces.md D4): the glyph comes
 * from the origin's KIND, never from its words — a workflow named «Main agent»
 * still draws the curve path. The words are pod-supplied text, escaped.
 */
const ASK_KINDS = ["main", "subagent", "workflow"];
/** The origin glyph's point size (the app's `AskCard` origin row). */
const ASK_GLYPH_PT = 17;
/** The collapsed command's visual rows (`PREVIEW_ROWS` in `command-preview.ts`). */
const ASK_PREVIEW_ROWS = 4;

/**
 * Polpetto's 9×9 silhouette, the app's own mask (`polpetto-glyph.ts`), as
 * horizontal runs per row: ~20 `<i>`s, not 81.
 */
function polpettoGlyph(size) {
  const unit = size / 9;
  const rows = vm.polpettoMask
    .map((row, y) => {
      const runs = [];
      for (let x = 0; x < row.length; x += 1) {
        if (!row[x]) continue;
        let w = 1;
        while (row[x + w]) w += 1;
        runs.push(
          `<i style="left:${(x * unit).toFixed(2)}pt;top:${(y * unit).toFixed(2)}pt;width:${(w * unit).toFixed(2)}pt;height:${unit.toFixed(2)}pt"></i>`,
        );
        x += w - 1;
      }
      return runs.join("");
    })
    .join("");
  return `<span class="k-ask-p" style="width:${size}pt;height:${size}pt" aria-hidden="true">${rows}</span>`;
}

/** The origin's glyph, chosen by KIND (`main` = Polpetto, the only non-SF one). */
function askGlyph(kind, size = ASK_GLYPH_PT) {
  if (kind === "main") return polpettoGlyph(size);
  return icon(
    kind === "subagent"
      ? "arrow.triangle.branch"
      : "point.topleft.down.to.point.bottomright.curvepath",
    { size },
  ).html;
}

function askOriginRow(origin = {}) {
  const kind = ASK_KINDS.includes(origin.kind) ? origin.kind : "main";
  const rest = origin.rest ? `<span class="ot"> ${esc(origin.rest)}</span>` : "";
  const age =
    origin.age === undefined || origin.age === ""
      ? ""
      : `<span class="k-ask-age">${esc(origin.age)}</span>`;
  return `<div class="k-ask-o" data-glyph="${kind}">${askGlyph(kind)}<span class="k-ask-lead"><b>${esc(origin.lead ?? "Main agent")}</b>${rest}</span>${age}</div>`;
}

/** The command box: `rows` visual rows, the rest behind `+N lines · Show all`. */
function askCommand(command, expanded) {
  const lines = String(command).split("\n");
  const shown = expanded ? lines : lines.slice(0, ASK_PREVIEW_ROWS);
  const body = shown.map((l) => `<div class="k-ask-ln">${esc(l) || " "}</div>`).join("");
  const foot =
    lines.length <= ASK_PREVIEW_ROWS
      ? ""
      : `<div class="k-ask-ft"><span>${expanded ? `${lines.length} lines` : `+${lines.length - ASK_PREVIEW_ROWS} lines`}</span><span class="lk">${expanded ? "Show less" : "Show all"} ${icon("chevron.up", { size: 11, weight: "bold" }).html}</span></div>`;
  return `<div class="k-ask-c"${expanded ? " data-x" : ""}><div class="bd">${body}</div>${foot}</div>`;
}

/**
 * THE ask card (docs/fix/mobile-ask-surfaces.md D4; `ui/AskCard.tsx`): origin row,
 * title, the four-row command, then `…  Deny  Allow once` — the actions OUTSIDE
 * the scroll, so they stay reachable at every detent. Deny is grey (the words
 * carry the meaning), Allow is the accent fill.
 *
 * `actions` replaces the default pair: `permissionSheet` passes its own answer
 * pills, because a `workflow_approve` offers allow-once / deny only.
 */
export function askCard({
  origin = {},
  title = "Run a shell command",
  command = "",
  expanded = false,
  menu = null,
  alsoAsked = "",
  armed = true,
  on = "sheet",
  actions = null,
} = {}) {
  const items = Array.isArray(menu) ? menu : [];
  const more =
    items.length > 0
      ? `<span class="k-ask-mo" aria-label="More options">${icon("ellipsis", { size: 19 }).html}</span>`
      : `<span class="k-ask-sp"></span>`;
  const open =
    items.length > 0
      ? `<div class="k-ask-menu">${items.map((l) => `<div><span>${esc(l)}</span></div>`).join("")}</div>`
      : "";
  const also = alsoAsked ? `<div class="k-ask-also">${esc(alsoAsked)}</div>` : "";
  const arming = armed ? "" : `<div class="k-ask-arming">Hold on…</div>`;
  const answers =
    actions ??
    '<span class="k-ask-b">Deny</span><span class="k-ask-b" data-primary>Allow once</span>';
  return out(
    `<div class="k-ask" data-on="${esc(on)}">${askOriginRow(origin)}<div class="k-ask-t">${esc(title)}</div>${askCommand(command, expanded)}${also}${arming}<div class="k-ask-a">${more}${answers}</div>${open}</div>`,
    `${origin.lead ?? "Main agent"} ${title}`,
  );
}

/**
 * The one-row ask (`ui/AskSlim.tsx`) — the peek detent and the banner under the
 * header. It never draws an answer: the command is not seen from here.
 */
export function askSlim({ title = "Run a shell command", origin = {}, go = "Review" } = {}) {
  const short = origin.short ?? origin.lead ?? "Main agent";
  const more = origin.more > 0 ? ` · +${esc(origin.more)}` : "";
  return out(
    `<div class="k-ask-slim"><span class="hd">${icon("hand.raised", { size: 18 }).html}</span><span class="tx"><b>${esc(title)}</b><span class="k-ask-o">${esc(short)}${more}</span></span><span class="go">${esc(go)} ${icon("chevron.up", { size: 12, weight: "bold" }).html}</span></div>`,
    `${title} — ${short}`,
  );
}

/**
 * The ask inside the formSheet frame (`PermissionSheet.tsx`): the grabber, the
 * caller's content, and the dim only ABOVE the peek detent — at the peek the
 * screen behind stays usable (`sheetLargestUndimmedDetentIndex: 0`).
 */
export function askSheet({ detent = "ask", inner = "" } = {}) {
  if (!["peek", "ask", "large"].includes(detent))
    throw new Error(`K.askSheet: unknown detent "${detent}" (peek | ask | large)`);
  return out(
    `<div class="k-ask-wrap"${detent === "peek" ? "" : " data-dim"}><div class="k-ask-sheet" data-detent="${detent}"><span class="k-grabber"></span>${inner}</div></div>`,
  );
}

/**
 * The approval sheet (`PermissionSheet`): the ask CARD inside the sheet frame —
 * S9 realigned it to `PermissionSheet.tsx`, which draws `AskCard` at every
 * detent above the peek. `options` stays a parameter because the answers are not
 * always the permission ones: `workflow_approve` offers allow-once / deny only.
 * `tool` survives as the frame's accessible name (the card has no tool row).
 */
export function permissionSheet({
  origin = { kind: "main", lead: "Main agent" },
  title = "Run a command?",
  tool = "shell",
  detail = "",
  diff = null,
  options = PERMISSION_OPTIONS,
} = {}) {
  const card = askCard({
    origin,
    title,
    command: diff ? diff.join("\n") : detail,
    actions: permOptions(options),
  });
  const frame = sheet({ children: [card.html] });
  return out(frame.html, `${card.a11y} (${tool})`);
}

export const pill = ({ text, dot = false }) =>
  out(`<span class="k-pill">${dot ? headerDot("running").html : ""}${esc(text)}</span>`, text);
/** A toast: one line, plus an optional action (`Undo`) on the same row. */
export const toast = ({ text, action = "" }) =>
  out(
    `<div class="k-toast">${esc(text)}${action ? `<span class="k-toast-action">${esc(action)}</span>` : ""}</div>`,
    text,
  );
export const banner = ({ text }) => out(`<div class="k-banner">${esc(text)}</div>`, text);

/** The floating hub button: `running` adds the turning arc; `opacity` = its rest level. */
export function hubButton({ running = false, opacity = 1, right = 10, bottom = 120 } = {}) {
  return out(
    `<div class="k-hub" style="right:${right}px;bottom:${bottom}px;opacity:${opacity}"><div class="k-hub-body"><span class="k-hub-grid"><i></i><i></i><i></i><i></i></span></div>${running ? '<span class="k-hub-arc"></span>' : ""}</div>`,
    running ? "Activity, running" : "Activity",
  );
}

/** The fan: items laid on an arc above the button (a sketch of `fanLayout`). */
export function hubFan({
  items = ["new", "sessions", "activity", "more"],
  right = 10,
  bottom = 120,
} = {}) {
  const r = 110;
  const html = items
    .map((it, i) => {
      const a = (Math.PI / 2) * (i / Math.max(1, items.length - 1));
      const x = right + Math.cos(a) * r;
      const y = bottom + Math.sin(a) * r;
      return `<span class="k-hub-item" style="right:${x.toFixed(1)}px;bottom:${y.toFixed(1)}px" title="${esc(it)}">${esc(it.slice(0, 1).toUpperCase())}</span>`;
    })
    .join("");
  return out(`${html}${hubButton({ right, bottom }).html}`);
}

/**
 * Polpetto at home (`MascotScene.tsx`): the rects `mascot-scenes.ts` `pixels`
 * draws (`KIT.data.viewModels.mascot`, mint), `frame` ∈ still | skate. Placed
 * centred, `homeInset` above the band's bottom (`homeAt`); `inset` overrides it.
 */
export function polpetto({ frame = "still", inset } = {}) {
  const m = vm.mascot;
  const rects = m[frame];
  if (!rects) throw new Error(`K.polpetto: no frame "${frame}" (still | skate)`);
  const xs = rects.map((r) => r.x);
  const x0 = Math.min(0, ...xs);
  const w = Math.max(m.sprite, ...rects.map((r) => r.x + r.w)) - x0;
  const h = Math.max(m.sprite, ...rects.map((r) => r.y + r.h));
  const body = rects
    .map(
      (r) =>
        `<rect x="${r.x - x0}" y="${r.y}" width="${r.w}" height="${r.h}" fill="${r.color}" opacity="${r.alpha}"/>`,
    )
    .join("");
  return out(
    `<span class="k-mascot" style="bottom:${(inset ?? m.homeInset) - (h - m.sprite)}px;margin-left:${x0 - m.sprite / 2}px"><svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" shape-rendering="crispEdges" aria-hidden="true">${body}</svg></span>`,
  );
}

/** The `EmptyState` standard: one line, one action. */
export function emptyAction({ text = "Nothing running", action = "" } = {}) {
  return out(
    `<div class="k-empty k-t-subhead">${esc(text)}${action ? `<span class="k-accent">${esc(action)}</span>` : ""}</div>`,
    text,
  );
}

/**
 * An E2 row: icon tile, title, subtitle, value, and — for a settings row — a
 * `control` SLOT (raw HTML: stepper, segmented, switch, chevron) and `mono` for
 * a value that is code (a command, a hash).
 */
export function row({ title, subtitle = "", value = "", icon = "", control = "", mono = false }) {
  return out(
    `<div class="k-list-row">${icon ? `<span class="k-tile">${esc(icon)}</span>` : ""}<div class="k-row-text"><span class="k-t-body">${esc(title)}</span>${subtitle ? `<span class="k-t-footnote k-sec">${esc(subtitle)}</span>` : ""}</div>${value ? `<span class="k-row-value k-t-body"${mono ? " data-mono" : ""}>${esc(value)}</span>` : ""}${control}</div>`,
    title,
  );
}

/**
 * The filled primary action (`--s-big-button`), e.g. "Save 5 files". `tone` ∈
 * accent | warn; `disabled` dims it AND says so to a reader.
 */
export function bigButton({ text = "", tone = "accent", disabled = false } = {}) {
  if (tone !== "accent" && tone !== "warn")
    throw new Error(`K.bigButton: unknown tone "${tone}" (accent | warn)`);
  return out(
    `<div class="k-big-button" data-tone="${esc(tone)}"${disabled ? ' data-disabled aria-disabled="true"' : ""}>${esc(text)}</div>`,
    disabled ? `${text}, unavailable` : text,
  );
}

/** An E2 band (square): its label, then rows. */
export function band({ label = "", rows = [] }) {
  return out(
    `<div class="k-section">${label ? `<div class="k-band-label">${esc(label)}</div>` : ""}<div class="k-band">${rows.map((r) => row(r).html).join("")}</div></div>`,
  );
}

/** Computers screen: per computer a header (status dot + line), then its sessions. */
export function computersList({ computers = [] } = {}) {
  return out(
    computers
      .map(
        (c) =>
          `<div class="k-computer-head"><div class="k-row-text"><span class="k-t-headline">${esc(c.name)}</span><span class="k-status-line k-t-footnote k-sec">${c.online ? toneDot("online") : toneDot("offline", { hollow: true })}${esc(c.status ?? (c.online ? "Online" : "Offline"))}</span></div><span class="k-icon-btn">…</span></div>${band({ rows: c.sessions ?? [] }).html}`,
      )
      .join(""),
  );
}

export const projectsList = ({ projects = [] } = {}) => band({ label: "Projects", rows: projects });

/** The sessions drawer: title, sections of rows, the current one highlighted. */
export function sessionsDrawer({ title = "Sessions", sections = [] } = {}) {
  return out(
    `<div class="k-drawer"><div class="k-drawer-title">${esc(title)}</div>${sections
      .map(
        (s) =>
          `<div class="k-drawer-section">${esc(s.label)}</div>${s.rows
            .map(
              (r) =>
                `<div class="k-drawer-row" ${r.current ? "data-current" : ""}><span style="flex:1;min-width:0">${esc(r.title)}</span><span class="k-drawer-meta">${esc(r.meta ?? "")}</span></div>`,
            )
            .join("")}`,
      )
      .join("")}</div>`,
  );
}

// ── «nuovo» ───────────────────────────────────────────────────────────────
const extensions = new Map();
/** Register a component the kit does not have: it renders outlined «nuovo» under `?nuovo=1`. */
export function extend(name, builder) {
  extensions.set(name, builder);
  const wrapped = (props) => {
    const r = builder(props);
    return out(
      `<div class="k-nuovo" data-nuovo="${esc(name)}">${r.html ?? r}</div>`,
      r.a11y ?? name,
    );
  };
  K[name] = wrapped;
  return wrapped;
}

// ── TUI ───────────────────────────────────────────────────────────────────
const tvm = vm.tui;
const ESC_CHAR = String.fromCharCode(27);
/** An SGR sequence (group 1: its params) or a run of text (group 2). */
const SGR_RE = new RegExp(`${ESC_CHAR}\\[([0-9;]*)m|([^${ESC_CHAR}]+)`, "g");
const BASIC = ["black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"];

function sgrColor(params, i) {
  // 38;2;r;g;b  (truecolor) | 38;5;n (256: not used by the TUI at level 3)
  if (params[i + 1] === 2)
    return { color: `rgb(${params[i + 2]}, ${params[i + 3]}, ${params[i + 4]})`, skip: 4 };
  if (params[i + 1] === 5) throw new Error("K.tui.fromAnsi: 256-colour SGR is not supported");
  return { color: null, skip: 0 };
}

/**
 * A REAL frame (SGR kept) → the kit's grid: `{ html, cells }`. `cells` is the
 * plain text per row (what calibration compares); colours are the frame's own.
 */
export function fromAnsi(text) {
  const lines = Array.isArray(text) ? text : String(text).split("\n");
  const cells = [];
  const rows = [];
  for (const line of lines) {
    let st = { fg: null, bg: null, bold: false, dim: false, inverse: false };
    let plain = "";
    let html = "";
    for (const m of line.matchAll(SGR_RE)) {
      if (m[2] !== undefined) {
        plain += m[2];
        const style = [st.fg ? `color:${st.fg}` : "", st.bg ? `background:${st.bg}` : ""]
          .filter(Boolean)
          .join(";");
        const flags = [
          st.bold ? "data-bold" : "",
          st.dim ? "data-dim" : "",
          st.inverse ? "data-inverse" : "",
        ].join(" ");
        html += `<span ${flags} style="${style}">${esc(m[2])}</span>`;
        continue;
      }
      const p = (m[1] === "" ? "0" : m[1]).split(";").map(Number);
      for (let i = 0; i < p.length; i += 1) {
        const c = p[i];
        if (c === 0) st = { fg: null, bg: null, bold: false, dim: false, inverse: false };
        else if (c === 1) st.bold = true;
        else if (c === 2) st.dim = true;
        else if (c === 22) {
          st.bold = false;
          st.dim = false;
        } else if (c === 7) st.inverse = true;
        else if (c === 27) st.inverse = false;
        else if (c === 39) st.fg = null;
        else if (c === 49) st.bg = null;
        else if (c === 38 || c === 48) {
          const r = sgrColor(p, i);
          if (c === 38) st.fg = r.color;
          else st.bg = r.color;
          i += r.skip;
        } else if (c >= 30 && c <= 37) st.fg = `var(--tui-ansi-${BASIC[c - 30]})`;
        else if (c >= 40 && c <= 47) st.bg = `var(--tui-ansi-${BASIC[c - 40]})`;
        else if (c === 90) st.fg = "var(--tui-ansi-gray)";
        else if (c >= 91 && c <= 97) st.fg = `var(--tui-ansi-${BASIC[c - 90]})`;
      }
    }
    cells.push(plain);
    rows.push(`<span class="k-tui-row">${html || " "}</span>`);
  }
  return { html: rows.join(""), cells, a11y: cells.join("\n") };
}

/** A grid wrapper in a TUI theme. */
function grid(theme, inner, reduceMotion = false) {
  return `<div class="k-tui" data-tui="${esc(theme)}" ${reduceMotion ? "data-reduce-motion" : ""}>${inner}</div>`;
}

/**
 * A transcript row, as the TUI's own `itemLines` rendered it (generated):
 * `name` ∈ user | assistant | toolRunning | toolOk | toolError. A running tool
 * blinks between its ON and OFF frames at `blinkHalfMs`.
 */
function transcriptRow(name, { theme = "dark", bare = false } = {}) {
  const rows = tvm.rows[theme]?.[name];
  if (!rows) throw new Error(`K.tui.transcriptRow: no rows for ${theme}/${name}`);
  const on = fromAnsi(rows);
  let inner = on.html;
  if (name === "toolRunning") {
    const off = fromAnsi(tvm.rows[theme].toolRunningOff);
    inner = `<span style="display:grid"><span style="grid-area:1/1">${off.html}</span><span class="k-tui-blink" style="grid-area:1/1;background:var(--tui-bg)">${on.html}</span></span>`;
  }
  return { html: bare ? inner : grid(theme, inner), cells: on.cells, a11y: on.a11y };
}

/** The thinking slot (`Thinking`): a braille frame, the label, the elapsed time. */
function slot({ seconds = 3, frame = 0, label = "Thinking…", theme = "dark" } = {}) {
  const dur = tvm.slot.duration[String(seconds)];
  if (dur === undefined)
    throw new Error(
      `K.tui.slot: no duration for ${seconds}s (have ${Object.keys(tvm.slot.duration)})`,
    );
  const glyph = tvm.slot.frames[frame % tvm.slot.frames.length];
  const hint = ` ${dur} · esc/ctrl+c to stop`;
  const html = `<span class="k-tui-row"><span class="k-tui-accent">${esc(glyph)} ${esc(label)}</span><span class="k-tui-dim">${esc(hint)}</span></span>`;
  return { html: grid(theme, html), cells: [`${glyph} ${label}${hint}`], a11y: `${label}${hint}` };
}

/** The prompt box (`LineInput`, rows from `inputRender`): `state` ∈ empty | draft. */
function inputBox({ state = "empty", placeholder = "", theme = "dark" } = {}) {
  const rows = tvm.input[state];
  if (!rows) throw new Error(`K.tui.inputBox: unknown state "${state}"`);
  const cells = [];
  const html = rows
    .map((r, i) => {
      const segs = r.segments
        .map((s) => `<span ${s.inverse ? "data-inverse" : ""}>${esc(s.text)}</span>`)
        .join("");
      const ph =
        state === "empty" && i === 0 ? `<span class="k-tui-dim">${esc(placeholder)}</span>` : "";
      cells.push(r.prefix + r.segments.map((s) => s.text).join("") + (ph ? placeholder : ""));
      return `<span class="k-tui-row"><span class="${r.gutter ? "k-tui-gutter" : "k-tui-accent"}">${esc(r.prefix)}</span>${segs}${ph}</span>`;
    })
    .join("");
  return { html: grid(theme, html), cells, a11y: cells.join("\n") };
}

const tui = { fromAnsi, transcriptRow, slot, inputBox, grid };

// ── mount ─────────────────────────────────────────────────────────────────
/** The per-dot breathe keyframes, from the generated `breatheCurve` samples. */
export function breatheKeyframes() {
  return vm.breathe.curves
    .map(
      (c, i) =>
        `@keyframes k-breathe-${i}{${c.inputRange.map((x, j) => `${(x * 100).toFixed(4)}%{opacity:${c.outputRange[j]}}`).join("")}}`,
    )
    .join("\n");
}

/** Mount a phone with `children` into `el` (browser only). */
export function screen(el, opts = {}, children = []) {
  const doc = el.ownerDocument;
  if (!doc.getElementById("k-breathe")) {
    const style = doc.createElement("style");
    style.id = "k-breathe";
    style.textContent = breatheKeyframes();
    doc.head.appendChild(style);
  }
  if (new URLSearchParams(doc.defaultView?.location.search ?? "").get("nuovo") === "1") {
    doc.documentElement.setAttribute("data-nuovo-mode", "");
  }
  el.innerHTML = phone(opts, children).html;
  return el.firstElementChild;
}

